import{_ as e,c as t,o as a,ag as i}from"./chunks/framework.B-XtCDNB.js";const r="/screenshots/security-visibility.png",c="/screenshots/security-permissions.png",o="/features/feat-audit-logging.png",n="/features/feat-data-encryption.png",d="/features/feat-payment-security.png",h=JSON.parse(`{"title":"Security","description":"Built with security as a priority. From encrypted data storage to granular user permissions, keep your store and your customers' data safe.","frontmatter":{"title":"Security","description":"Built with security as a priority. From encrypted data storage to granular user permissions, keep your store and your customers' data safe.","layout":"doc","aside":false},"headers":[],"relativePath":"features/security.md","filePath":"features/security.md"}`),l={name:"features/security.md"};function p(m,s,u,v,g,y){return a(),t("div",null,[...s[0]||(s[0]=[i('<div class="mc-features-page"><div class="mc-features-hero"><h1>Security</h1><p>Meloncart is built with security as a priority. From encrypted data storage to granular <strong>user permissions</strong>, the platform provides the tools you need to keep your store and your customers&#39; data safe.</p></div><div class="mc-detail-body"><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Page Access Control</h2><p>Control which pages are visible to different visitor types, including guests, authenticated customers or specific <strong>customer groups</strong>. Restrict access to wholesale catalogs, member-only content or account management pages with simple configuration.</p></div><div class="mc-detail-section__visual"><div class="mc-mockup"><div class="mc-mockup__bar"><span></span><span></span><span></span></div><div class="mc-mockup__screen"><img src="'+r+'" alt="Page access control"></div></div></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>User Permissions</h2><p>Control exactly what each backend user can access. Restrict permissions by area such as products, orders, themes and settings, so team members only see what&#39;s relevant to their <strong>role</strong>.</p><p>You can even limit order access based on order status, so a fulfillment team only sees orders that are ready to ship.</p></div><div class="mc-detail-section__visual"><div class="mc-mockup"><div class="mc-mockup__bar"><span></span><span></span><span></span></div><div class="mc-mockup__screen"><img src="'+c+'" alt="User permissions"></div></div></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Audit Logging</h2><p>Backend user logins are automatically logged, and critical database records track which user <strong>created</strong> or last <strong>modified</strong> them. This gives you a clear audit trail for accountability and troubleshooting.</p></div><div class="mc-detail-section__visual"><img src="'+o+'" alt="Audit logging"></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Data Encryption</h2><p>Sensitive data stored in the database is automatically <strong>encrypted</strong> by Meloncart. In the event of a database breach, encrypted fields remain protected.</p></div><div class="mc-detail-section__visual"><img src="'+n+'" alt="Data encryption"></div></div><div class="mc-detail-section"><div class="mc-detail-section__text"><h2>Payment Security</h2><p>Meloncart never stores credit card numbers. Payment data is handled directly by your payment gateway (Stripe, PayPal, etc.) using their secure APIs, keeping card details off your server entirely.</p><p>This minimizes your <strong>PCI compliance</strong> scope and reduces risk.</p></div><div class="mc-detail-section__visual"><img src="'+d+'" alt="Payment security"></div></div></div></div>',1)])])}const f=e(l,[["render",p]]);export{h as __pageData,f as default};
